import { realisticReactionScene } from './reaction-scenes.js';
import { reactionClock } from './components.js';
import { prepareStudio } from './studio.js';
export const demonstrations = [
 {id:'light',title:'發光與放熱',name:'鎂帶燃燒',before:'銀白色鎂帶，由坩堝鉗夾持在酒精燈上方。',during:'鎂帶燃燒，發出白光，並放出熱量。',after:'留下白色氧化鎂；這是與原來鎂帶不同的物質。',equation:'2Mg + O₂ → 2MgO',action:'點火，觀察鎂帶',product:'白色氧化鎂',note:'以柔和光暈代替實際強光；真實實驗勿直視燃燒的鎂。'},
 {id:'color',title:'顏色改變',name:'五水硫酸銅受熱',before:'蒸發皿內有藍色的五水硫酸銅晶體。',during:'持續加熱，晶體逐漸失去結晶水，藍色轉淡。',after:'留下白色的無水硫酸銅，水以水蒸氣離開。',equation:'CuSO₄·5H₂O → CuSO₄ + 5H₂O',action:'加熱，觀察顏色',product:'白色無水硫酸銅',note:'反應條件：加熱。以淡色軌跡標示水蒸氣去向；水蒸氣本身無色。'},
 {id:'solid',title:'生成沉澱',name:'碳酸鈉溶液＋氯化鈣溶液',before:'兩種溶液原本都透明，還沒有接觸。',during:'倒入氯化鈣溶液，混合處逐漸出現白色混濁。',after:'生成不溶於水的碳酸鈣，白色固體逐漸沉降。',equation:'Na₂CO₃ + CaCl₂ → CaCO₃↓ + 2NaCl',action:'混合，觀察沉澱',product:'白色碳酸鈣沉澱',note:'沉降過程經過加速。CaCO₃ 是固體，NaCl 仍溶在水中。'},
 {id:'gas',title:'產生氣體',name:'石灰石＋稀鹽酸',before:'燒杯內是石灰石與少量水；滴管內是稀鹽酸。',during:'酸滴到石灰石，固體表面出現持續上升的氣泡。',after:'生成的二氧化碳離開液面；石灰石逐漸減少。',equation:'CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂↑',action:'滴入，觀察氣泡',product:'二氧化碳氣體',note:'石灰石示意為過量，反應後仍有剩餘；氣體身分需另行檢驗。'}
];
export function phenomenonScene(id,p=0){return realisticReactionScene(id,p);}
export function reactionComparison(d){
 return '<div class="reaction-comparison-heading"><span class="studio-eyebrow">觀察完成 / 前後對照</span><h4>'+d.name+'：物質變成什麼了？</h4><p>比較材料的顏色、形態，以及新出現的物質。</p></div><div class="reaction-comparison-pair">'+[0,1].map(p=>'<figure><div class="reaction-comparison-label"><span>0'+(p+1)+'</span><b>'+(p?'反應後':'反應前')+'</b></div>'+realisticReactionScene(d.id,p,p?'comparison-after':'comparison-before')+'<figcaption><strong>'+(p?'生成新物質：'+d.product:'原來的材料')+'</strong><p>'+(p?d.after:d.before)+'</p></figcaption></figure>').join('')+'</div>';
}
export function mountPhenomena(root,ctx){
 let selected=0,p=0,running=false;const seen=new Set();
 root.classList.add('phenomena-studio');root.setAttribute('data-glossary-skip','');
 root.innerHTML='<div class="phenomena-tabs" role="group" aria-label="選擇反應示範">'+demonstrations.map((d,i)=>'<button data-demo="'+i+'" aria-pressed="'+(i===0)+'"><span>0'+(i+1)+'</span><b>'+d.title+'</b><small>'+d.name+'</small></button>').join('')+'</div><div class="reaction-theater"><div class="reaction-stage"><div class="reaction-stage-head"><span>實例觀察 / 教學動畫</span><b class="reaction-phase"></b></div><div class="reaction-art"></div><progress max="1" value="0" aria-label="反應示範進度"></progress></div><aside class="reaction-notes"><span class="studio-eyebrow">觀察一個真實反應的過程</span><h3 class="reaction-name"></h3><div class="reaction-observation" role="status"></div><div class="reaction-equation"></div><button class="primary demonstrate"></button><button class="text-button reaction-rewind">回到反應前</button></aside></div><section class="reaction-comparison" aria-label="反應前後的物質變化對照" hidden></section><p class="reaction-note"></p><div class="evidence-caution"><b>看到變化，還要確認是否生成新物質。</b><p>水沸騰也會冒泡，卻仍是 H₂O。這些動畫重現實驗現象，並非實拍；速度與外觀經過簡化。真實實驗需由教師指導。</p></div>';
 prepareStudio(root,{number:'02',title:'化學反應觀察室',description:'選一個實例，按下反應，觀察材料如何改變。'}, {predict:()=>true});
 function draw(){const d=demonstrations[selected],phase=p===0?'反應前':p===1?'反應後':running?'反應中':'已暫停';const comparison=root.querySelector('.reaction-comparison');if(p===1&&comparison.dataset.reaction!==d.id){comparison.innerHTML=reactionComparison(d);comparison.dataset.reaction=d.id;}comparison.hidden=p!==1;root.querySelector('.reaction-art').innerHTML=phenomenonScene(d.id,p);root.querySelector('.reaction-phase').textContent=phase;root.querySelector('progress').value=p;root.querySelector('.reaction-name').textContent=d.name;const observation='<span>'+phase+'</span><p>'+(p===0?d.before:p===1?d.after:d.during)+'</p>'+(p===1?'<b>新物質：'+d.product+'</b>':'');if(root.querySelector('.reaction-observation').innerHTML!==observation)root.querySelector('.reaction-observation').innerHTML=observation;root.querySelector('.reaction-equation').textContent=d.equation;root.querySelector('.reaction-note').textContent=d.note;root.querySelector('.demonstrate').textContent=running?'Ⅱ 暫停觀察':p===1?'↻ 再反應一次':p>0?'▶ 繼續觀察':'▶ 反應 · '+d.action;root.querySelectorAll('[data-demo]').forEach(b=>{b.setAttribute('aria-pressed',String(+b.dataset.demo===selected));b.classList.toggle('has-observed',seen.has(+b.dataset.demo));});}
 const clock=reactionClock((value,run)=>{p=value;running=run;draw();},()=>{seen.add(selected);ctx.mark();draw();});
 root.querySelector('.demonstrate').onclick=()=>{if(running)clock.pause();else{if(p===1)clock.reset();running=true;draw();clock.start();}};
 root.querySelector('.reaction-rewind').onclick=()=>clock.reset();root.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{clock.pause();selected=+b.dataset.demo;clock.reset();});draw();return{reset(){seen.clear();selected=0;clock.reset();}};
}
